cat <<'EOF' > app/controllers/searches_controller.rb
class SearchesController < ApplicationController
  def show
    @search = Search.new(user: Current.user, query: params[:q])
    set_page_and_extract_portion_from @search.cards
    @results = @search.results_for(@page.records)
  end
